import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-10-31 02:00 Warsaw (CET, UTC+1 after the DST change on 2026-10-25)
    private static final Clock NIGHT = Clock.fixed(Instant.parse("2026-10-31T01:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, NIGHT);

    private String placed(String placedAt, String status) {
        String id = service.place("c-1", Money.pln(100), Instant.parse(placedAt));
        if (!"PLACED".equals(status)) {
            orders.get(id).changeStatus(status);
        }
        return id;
    }

    @Test
    void cancelsPlacedOrdersOlderThan30Days() {
        String old = placed("2026-09-20T10:00:00Z", "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", service.summary(old).status());
    }

    @Test
    void keepsOrdersPlacedWithin30Days() {
        String recent = placed("2026-10-01T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(recent).status());
    }

    @Test
    void exactly30DaysAgoIsNotMoreThan30DaysAgo() {
        // 2026-10-01 is exactly 30 calendar days before 2026-10-31 in Warsaw.
        String edge = placed("2026-10-01T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(edge).status());
    }

    @Test
    void leavesOrdersInOtherStatusesAlone() {
        String confirmed = placed("2026-09-01T10:00:00Z", "CONFIRMED");
        String cancelled = placed("2026-09-01T10:00:00Z", "CANCELLED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", service.summary(confirmed).status());
        assertEquals("CANCELLED", service.summary(cancelled).status());
    }

    @Test
    void usesTheWarsawCalendarDay() {
        // 2026-09-30 23:30 UTC is 2026-10-01 01:30 Warsaw, so it is on the 1st, not the 30th.
        // The cutoff is 2026-10-01, so this order is not yet stale.
        String lateNight = placed("2026-09-30T23:30:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", service.summary(lateNight).status());
    }

    @Test
    void countsOnlyTheOrdersItCancelled() {
        placed("2026-09-01T10:00:00Z", "PLACED");
        placed("2026-09-02T10:00:00Z", "PLACED");
        placed("2026-10-30T10:00:00Z", "PLACED");
        placed("2026-09-03T10:00:00Z", "CONFIRMED");

        assertEquals(2, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
